import math


TX_MIN, TX_MAX = 28.0, 32.0


TY_MIN, TY_MAX = 2.0, 5.0


TARGET_X, TARGET_Y = 30.0, 3.5


G1_X, G1_Y = 13.0, 2.0


G2_X, G2_Y = 23.0, 2.4


DRAIN_LO, DRAIN_HI = 14.5, 17.0


SLIP_LO, SLIP_HI = 17.5, 20.0


WIND_LO, WIND_HI = 20.5, 28.0


WIND_AMP = 20.0


WIND_OMEGA = 0.055


MAX_THRUST = 120.0


LOW_THRUST = 90.0


HEAT_SAFE_FRAC = 0.88


def _waypoint(x, y):
    if x < G1_X - 0.1:
        return (G1_X, G1_Y)
    if x < G2_X - 0.1:
        return (G2_X, G2_Y)
    return (TARGET_X, TARGET_Y)


def build_agent(sandbox):
    return None


def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return
    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat
    step_idx = sandbox.get_step_count() if hasattr(sandbox, "get_step_count") else step_count
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 75.0)
        return
    if x > 31.0 and y < 2.0:
        sandbox.apply_thrust(-150.0, 200.0)
        return
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.25)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.35)
    if overheat_limit <= 40000.0:
        heat_frac = heat / overheat_limit
        if heat_frac > 0.3:
            thrust_mag = 40.0
        else:
            thrust_mag = 60.0
    if x < 10.0:
        thrust_mag = min(100.0, thrust_mag)
    if 10.0 <= x <= 15.0:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.2)
    if DRAIN_LO <= x <= DRAIN_HI:
        thrust_mag = min(MAX_THRUST, thrust_mag * 1.4)
    if thrust_mag < 75.0 and overheat_limit > 40000.0:
        sandbox.apply_thrust(0.0, 75.0)
        return
    wx, wy = _waypoint(x, y)
    if x > 24.0:
        wy = 4.0
    if x < G1_X + 0.5 and y < 1.2:
        wy = max(wy, 1.3)
    if y < 1.4:
        wy = max(wy, 1.5)
    if G2_X - 1.0 <= x <= G2_X + 2.0 and y < 1.9:
        wy = max(wy, 2.2)
    if 20.5 <= x <= G2_X + 1.0 and y < 1.85:
        wx, wy = x + 0.3, 2.5
    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx * dx + dy * dy)
    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return
    ux = dx / dist
    uy = dy / dist
    fx = thrust_mag * ux
    fy = thrust_mag * uy
    if y < 1.4:
        fy += 100.0
    if x < G1_X + 1.0 and y < 1.1:
        fy += min(30.0, (1.2 - y) * 40.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        fy += 110.0
    if x > 25.0 and y < 3.0:
        fy += 120.0
    if SLIP_LO <= x <= SLIP_HI:
        fx += 35.0
    if WIND_LO <= x <= WIND_HI:
        wind_fy = WIND_AMP * math.sin(WIND_OMEGA * step_idx)
        fy -= wind_fy
    total = math.sqrt(fx * fx + fy * fy)
    cap = thrust_mag * 2.5
    if y < 1.4:
        cap = max(cap, 180.0)
    if 20.5 <= x <= G2_X + 2.0 and y < 1.9:
        cap = max(cap, 250.0)
    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale
    sandbox.apply_thrust(fx, fy)

import math

TX_MIN, TX_MAX = 28.0, 32.0
TY_MIN, TY_MAX = 2.0, 5.0
TARGET_X, TARGET_Y = 30.0, 3.5
G1_X, G1_Y = 12.0, 1.4  # Gate 1: x [12.0,14.0], y [1.0,2.8]
G2_X, G2_Y = 22.0, 1.9  # Gate 2: x [22.0,24.0], y [1.8,3.0]
MAX_THRUST = 250.0  # Increased base thrust to overcome drag
LOW_THRUST = 150.0
HEAT_SAFE_FRAC = 0.80

# State machine states
STATE_GATE1 = 0
STATE_GATE2 = 1
STATE_TARGET = 2

def _waypoint(x, y, state):
    if state == STATE_GATE1:
        # Target Gate 1 exit point (center of gate) with mid-range y
        return (G1_X + 1.0, G1_Y + 1.2)  # (13.0, 2.6)
    elif state == STATE_GATE2:
        # Target Gate 2 exit point (center of gate) with mid-range y
        return (G2_X + 1.0, G2_Y + 1.0)  # (23.0, 2.9)
    else:
        # Target final zone
        return (TARGET_X, TARGET_Y)

def build_agent(sandbox):
    # No physical agent needed; control is done via thrust API
    return None

def agent_action(sandbox, agent_body, step_count):
    if sandbox.is_overheated():
        return

    pos = sandbox.get_craft_position()
    if pos is None:
        return
    x, y = pos
    heat = sandbox.get_heat()
    overheat_limit = sandbox.get_overheat_limit()
    remaining = overheat_limit - heat

    # State machine with combined x/y checks
    current_state = STATE_GATE1
    if x >= G1_X + 1.0 and 1.0 <= y <= 2.8:
        # Confirm passage through Gate 1 by checking proximity to exit point
        if abs(x - (G1_X + 1.0)) < 0.5 and abs(y - (G1_Y + 1.2)) < 0.5:
            current_state = STATE_GATE2
    if x >= G2_X + 1.0 and 1.8 <= y <= 3.0:
        # Confirm passage through Gate 2 by checking proximity to exit point
        if abs(x - (G2_X + 1.0)) < 0.5 and abs(y - (G2_Y + 1.0)) < 0.5:
            current_state = STATE_TARGET

    # Target zone check
    if TX_MIN <= x <= TX_MAX and TY_MIN <= y <= TY_MAX:
        sandbox.apply_thrust(0.0, 75.0)
        return

    # Heat management with dynamic scaling
    if heat >= overheat_limit * HEAT_SAFE_FRAC:
        thrust_mag = min(LOW_THRUST, remaining * 0.25)
    else:
        thrust_mag = min(MAX_THRUST, remaining * 0.35)

    # Waypoint targeting with y-range constraints
    wx, wy = _waypoint(x, y, current_state)

    # Prevent drift outside gate y-ranges with proportional correction
    if current_state == STATE_GATE1:
        if y < 1.0:
            wy = max(wy, 1.0)
        elif y > 2.8:
            wy = min(wy, 2.8)
    elif current_state == STATE_GATE2:
        if y < 1.8:
            wy = max(wy, 1.8)
        elif y > 3.0:
            wy = min(wy, 3.0)

    # Vertical corrections based on position, not velocity
    if current_state == STATE_GATE1 and y < 1.4:
        wy = max(wy, 1.5)  # Proportional upward correction
    if current_state == STATE_GATE2 and y < 1.9:
        wy = max(wy, 2.2)  # Proportional upward correction

    # Horizontal correction if stuck in gate region
    if 11.0 <= x <= 14.0 and y > 2.8:
        wx = x + 0.5  # Push forward if too high in Gate 1
    if 21.0 <= x <= 24.0 and y > 3.0:
        wx = x + 0.5  # Push forward if too high in Gate 2

    dx = wx - x
    dy = wy - y
    dist = math.sqrt(dx*dx + dy*dy)

    if dist < 1e-6:
        sandbox.apply_thrust(0.0, 75.0)
        return

    ux = dx / dist
    uy = dy / dist

    # Thrust vector calculation with vertical limits
    fx = thrust_mag * ux
    fy = thrust_mag * uy

    # Cap total thrust to prevent overexertion
    total = math.sqrt(fx*fx + fy*fy)
    cap = thrust_mag * 2.0
    if total > cap:
        scale = cap / total
        fx *= scale
        fy *= scale

    # Add forward bias when near gates to prevent stalling
    if 11.0 <= x <= 14.0:
        fx += 40.0
    if 21.0 <= x <= 24.0:
        fx += 40.0

    # Fallback trajectory if straying too far from target
    if abs(x - TARGET_X) > 10.0 or abs(y - TARGET_Y) > 10.0:
        fx = 200.0
        fy = 0.0

    sandbox.apply_thrust(fx, fy)

